data.script:
function check(value,message){if(!value)throw new Error(message);}
check(action.configuredValues===context.configuredValues && context.configuredValues.local===true,'own context');
const snapshots=[Action.find('QA Typed configuration source'),ActionGroup.find('Native typed values source').actions[0],Action.recent().find(a=>a.name==='QA Typed configuration source')];
for(const item of snapshots){
 check(item,'source present; run source first');
 const v=item.configuredValues;
 check(v.enabled===false && v.count===3.5 && v.label==='café 🐼\nText','typed source snapshot');
 check(Reflect.set(item,'configuredValues',{})===false,'readonly property');
}
check(context.configuredValues.local===true && context.configuredValues.count===undefined,'context unchanged');
editor.setText('Typed other-action configuration passed café 🐼');draft.update();
